export const W=1000,H=900,MAX_STROKES=1200,MAX_POINTS=120000;
export const TOOLS=['marker','crayon','soft','spray','sand','stamp','ribbon','eraser'],STAMPS=['star','heart','flower'];
export function coordinate(x,y,rect){return {x:Math.max(0,Math.min(W,(x-rect.left)/rect.width*W)),y:Math.max(0,Math.min(H,(y-rect.top)/rect.height*H))}}
export function validDocument(v,ids){if(!v||(v.numbers!==undefined&&typeof v.numbers!=='boolean')||(v.background!==undefined&&!/^#[0-9a-f]{6}$/i.test(v.background))||v.version!==1||!ids.includes(v.pattern)||!Array.isArray(v.strokes)||v.strokes.length>MAX_STROKES)return false;let n=0;return v.strokes.every(s=>s&&(s.rainbow===undefined||typeof s.rainbow==='boolean')&&TOOLS.includes(s.tool)&&/^#[0-9a-f]{6}$/i.test(s.color)&&[9,20,38].includes(s.size)&&(s.seed===undefined||Number.isInteger(s.seed)&&s.seed>=0&&s.seed<=4294967295)&&(s.stamp===undefined||STAMPS.includes(s.stamp))&&Array.isArray(s.points)&&s.points.length>0&&s.points.length<15000&&(n+=s.points.length)<=MAX_POINTS&&s.points.every(p=>Number.isFinite(p.x)&&p.x>=0&&p.x<=W&&Number.isFinite(p.y)&&p.y>=0&&p.y<=H))}
// Seeded particles and distance-spaced marks replay identically after restore/export.
export function random(seed){let n=seed>>>0;return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296}}
export function spaced(points,step,max=700){let length=0;for(let i=1;i<points.length;i++)length+=Math.hypot(points[i].x-points[i-1].x,points[i].y-points[i-1].y);step=Math.max(step,length/Math.max(1,max-1));const out=[points[0]];let carry=0;for(let i=1;i<points.length&&out.length<max;i++){const a=points[i-1],b=points[i],d=Math.hypot(b.x-a.x,b.y-a.y);if(!d)continue;let at=step-carry;for(;at<=d&&out.length<max;at+=step)out.push({x:a.x+(b.x-a.x)*at/d,y:a.y+(b.y-a.y)*at/d});carry=(carry+d)%step}return out}
// Distance-based hue; no wall clock or new randomness enters replay.
export function rainbowColor(distance){return `hsl(${Math.round(distance*.85)%360} 82% 55%)`}
function coloredMarks(points){let distance=0;return points.map((p,i)=>{if(i)distance+=Math.hypot(p.x-points[i-1].x,p.y-points[i-1].y);return {...p,distance,color:rainbowColor(distance)}})}
function stamp(ctx,p,r,shape){ctx.beginPath();if(shape==='heart'){ctx.moveTo(p.x,p.y+r*.8);ctx.bezierCurveTo(p.x-r*1.7,p.y-r*.3,p.x-r*.75,p.y-r*1.4,p.x,p.y-r*.55);ctx.bezierCurveTo(p.x+r*.75,p.y-r*1.4,p.x+r*1.7,p.y-r*.3,p.x,p.y+r*.8)}else{const count=shape==='flower'?60:10;for(let i=0;i<count;i++){const a=-Math.PI/2+i*Math.PI*2/count,rad=shape==='flower'?r*(.75+.25*Math.cos(5*a)):r*(i%2?.46:1),x=p.x+Math.cos(a)*rad,y=p.y+Math.sin(a)*rad;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()}ctx.fill()}
export function drawStroke(ctx,s){if(!s.points.length)return;ctx.save();ctx.globalCompositeOperation=s.tool==='eraser'?'destination-out':'source-over';ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=s.size*(s.tool==='eraser'?2:1);ctx.globalAlpha=s.tool==='soft'?.25:1;
const isRainbow=s.rainbow===true&&s.tool!=='eraser';
const path=(colored=true)=>{if(isRainbow&&colored){const originalCap=ctx.lineCap;ctx.lineCap='round';const marks=coloredMarks(spaced(s.points,Math.max(2,s.size*.15),700)),end=s.points.at(-1);if(marks.at(-1).x!==end.x||marks.at(-1).y!==end.y){const last=marks.at(-1),distanceColor=rainbowColor(last.distance+Math.hypot(end.x-last.x,end.y-last.y));marks.push({...end,color:distanceColor})}if(marks.length===1){ctx.fillStyle=marks[0].color;ctx.beginPath();ctx.arc(marks[0].x,marks[0].y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill()}else for(let i=1;i<marks.length;i++){ctx.strokeStyle=marks[i].color;ctx.beginPath();ctx.moveTo(marks[i-1].x,marks[i-1].y);ctx.lineTo(marks[i].x,marks[i].y);ctx.stroke()}ctx.lineCap=originalCap;return}ctx.beginPath();ctx.moveTo(s.points[0].x,s.points[0].y);for(const p of s.points.slice(1))ctx.lineTo(p.x,p.y);if(s.points.length===1){ctx.arc(s.points[0].x,s.points[0].y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill()}else ctx.stroke()};
if(s.tool==='spray'||s.tool==='sand'){const rnd=random(s.seed??12345),spray=s.tool==='spray',marks=coloredMarks(spaced(s.points,Math.max(4,s.size*.35))); for(const p of marks){for(let i=0;i<(spray?18:24);i++){const a=rnd()*Math.PI*2,rr=Math.sqrt(rnd())*s.size*(spray?1.25:.6),x=p.x+Math.cos(a)*rr,y=p.y+Math.sin(a)*rr;ctx.globalAlpha=spray?.18+rnd()*.35:.55+rnd()*.4;const grain=spray?.5+rnd()*1.2:1+rnd()*2.1;ctx.fillStyle=!spray&&i%5===0?'#fff4d2':isRainbow?p.color:s.color;if(spray){ctx.beginPath();ctx.arc(x,y,grain,0,Math.PI*2);ctx.fill()}else ctx.fillRect(x,y,grain,grain)}}
}else if(s.tool==='stamp'){for(const p of coloredMarks(spaced(s.points,s.size*2.6,350))){if(isRainbow)ctx.fillStyle=p.color;stamp(ctx,p,s.size*1.15,s.stamp||'star')}
}else if(s.tool==='ribbon'){ctx.lineCap='butt';ctx.lineJoin='round';ctx.lineWidth=s.size*1.8;path();ctx.globalAlpha=.42;ctx.strokeStyle='#ffffff';ctx.fillStyle='#ffffff';ctx.lineWidth=s.size*.5;path(false);ctx.globalAlpha=.16;ctx.strokeStyle='#35444a';ctx.lineWidth=Math.max(1,s.size*.1);path(false)
}else if(s.tool==='crayon'){ctx.globalAlpha=.7;ctx.lineWidth=s.size*.72;path();ctx.globalAlpha=.25;ctx.lineWidth=s.size;ctx.setLineDash([2,4]);path()}else path();ctx.restore()}

export function backgroundColor(state){return /^#[0-9a-f]{6}$/i.test(state.background||'')?state.background:'#ffffff'}
